export const getReportsTrafficUrl = (params?: ReportsTrafficParams) => {
	const normalizedParams = new URLSearchParams();

	Object.entries(params || {}).forEach(([key, value]) => {
		if (value !== undefined) {
			normalizedParams.append(key, value === null ? "null" : String(value));
		}
	});

	const stringifiedParams = normalizedParams.toString();

	return stringifiedParams.length > 0
		? `/api/v1/reports/traffic?${stringifiedParams}`
		: `/api/v1/reports/traffic`;
};

/**
 * Fleet and per-server bytes, peak day and hour, relay-exit pair bytes (default 7 days).
 * @summary Traffic
 */
export const reportsTraffic = async (
	params?: ReportsTrafficParams,
	options?: Parameters<typeof apiFetch>[1],
): Promise<TrafficReport> => {
	return apiFetch<TrafficReport>(getReportsTrafficUrl(params), {
		...options,
		method: "GET",
	});
};

export const getReportsTrafficQueryKey = (params?: ReportsTrafficParams) => {
	return [`/api/v1/reports/traffic`, ...(params ? [params] : [])] as const;
};

export const useReportsTrafficQueryOptions = <
	TData = Awaited<ReturnType<typeof reportsTraffic>>,
	TError = ErrorType<HTTPValidationError>,
>(
	params?: ReportsTrafficParams,
	options?: {
		query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof reportsTraffic>>, TError, TData>>;
		request?: SecondParameter<typeof apiFetch>;
	},
) => {
	const { query: queryOptions, request: requestOptions } = options ?? {};

	const queryKey = queryOptions?.queryKey ?? getReportsTrafficQueryKey(params);

	const queryFn: QueryFunction<Awaited<ReturnType<typeof reportsTraffic>>> = ({ signal }) =>
		reportsTraffic(params, { signal, ...requestOptions });

	const customOptions = queryDefaults({ queryKey, queryFn, ...queryOptions });

	return customOptions as UseQueryOptions<
		Awaited<ReturnType<typeof reportsTraffic>>,
		TError,
		TData
	> & { queryKey: DataTag<QueryKey, TData, TError> };
};

